(function () {
  "use strict";
  var posters = {
  "poster-1": "data:image/png;base64,",
  "poster-2": "data:image/png;base64,",
  "poster-3": "data:image/png;base64,"
};
  document.querySelectorAll("img[data-poster-image]").forEach(function (image) {
    var source = posters[image.dataset.posterImage];
    if (source) image.src = source;
  });
})();
